-- ============================================================================
-- Migration: 004_add_impact_field.sql
-- Description: Add impact field to votes table
-- Date: 2025-10-08
-- ============================================================================

-- Purpose:
-- Add impact classification field to capture AI-generated assessment of
-- vote importance (high, medium, low). This field is generated by the
-- AI processor and helps users filter/sort by significance.

-- Ensure UUID extension is enabled (consistency with other migrations)
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- ============================================================================
-- Add impact field to votes table
-- ============================================================================

ALTER TABLE votes
ADD COLUMN IF NOT EXISTS impact VARCHAR(20)
  CHECK (impact IN ('high', 'medium', 'low'));

-- Add index for filtering by impact
CREATE INDEX IF NOT EXISTS idx_votes_impact ON votes(impact);

-- ============================================================================
-- Comments for documentation
-- ============================================================================

COMMENT ON COLUMN votes.impact IS 'AI-generated impact assessment: high (policy changes, major budget), medium (important approvals), low (procedural/admin)';

-- ============================================================================
-- Verification queries
-- ============================================================================

-- Verify column was added
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_name = 'votes'
          AND column_name = 'impact'
    ) THEN
        RAISE NOTICE '✓ impact column added successfully';
    ELSE
        RAISE EXCEPTION '✗ Failed to add impact column';
    END IF;
END $$;

-- Verify check constraint exists
SELECT constraint_name, check_clause
FROM information_schema.check_constraints
WHERE constraint_name LIKE '%impact%';

-- Expected output: constraint checking impact IN ('high', 'medium', 'low')

-- ============================================================================
-- Rollback (if needed)
-- ============================================================================

